"""Edge-case-heavy randomized cross-check, including multi-run requests."""
import json, random, sys
sys.path.insert(0, '/workspace'); sys.path.insert(0, '/workspace/submission')
import ref
from runner import same
from utils import run_request


def gen_run(rng, mode):
    if mode == 'edge':
        M = rng.choice([1, 1, 2, 16]); L = rng.choice([1, 1, 8])
        R = rng.choice([1, 1, 2, 64]); fcap = rng.choice([1, 2, 10, 10**6])
        pcap = rng.choice([1, 2, 10, 10**6]); batch = rng.choice([1, 32])
        period = rng.choice([1, 1, 2, 100000]); neflow = rng.choice([1, 5])
        maxlen = rng.choice([1, 3, 1000]); U = rng.choice([1, 2, 5, 2147483647])
    else:
        M = rng.randint(1, 6); L = rng.randint(1, 4); R = rng.randint(1, 6)
        fcap = rng.randint(1, 60); pcap = rng.randint(1, 60)
        batch = rng.randint(1, 10); period = rng.randint(1, 10)
        neflow = rng.randint(1, 6); maxlen = rng.randint(1, 30)
        U = rng.randint(1, 40)
    if R == 1 or U == 1:
        borders = [0, max(1, U)]
    else:
        k = min(R - 1, U - 1)
        borders = [0] + sorted(rng.sample(range(1, U), k)) + [U]
    kind = rng.choice(['fifo', 'sp', 'sff', 'wfq', 'wfq'])
    flows = list(range(neflow))
    if kind == 'sp':
        policy = {'kind': 'sp', 'levels': [[f, rng.choice([0, 1, 7, 2147483647])] for f in flows]}
    elif kind == 'wfq':
        policy = {'kind': 'wfq', 'weights': [[f, rng.choice([1, 2, 1024])] for f in flows]}
    else:
        policy = {'kind': kind}
    events = []
    nid = 0
    save_names = []
    n = rng.randint(1, 140)
    for _ in range(n):
        c = rng.random()
        if c < 0.40:
            events.append(['enqueue', nid, rng.choice(flows), rng.randint(1, maxlen),
                           rng.choice([0, 1, rng.randint(0, 5000)])])
            nid += 1
        elif c < 0.62:
            events.append(['dequeue', rng.randint(1, 6)])
        elif c < 0.70:
            events.append(['sample'])
        elif c < 0.76:
            nb = rng.randint(1, 5); U2 = rng.choice([1, 3, 9, 2147483647])
            if nb == 1 or U2 == 1:
                bs = []
            else:
                bs = sorted(rng.sample(range(1, U2), min(nb - 1, U2 - 1)))
            events.append(['repartition', [0] + bs + [U2]])
        elif c < 0.84:
            events.append(['cancel', rng.randint(0, nid + 1)])
        elif c < 0.88:
            events.append(['inspect', rng.randint(0, nid + 1)])
        elif c < 0.92:
            if kind == 'wfq':
                events.append(['weight', rng.choice(flows), rng.choice([1, 3, 1024])])
            else:
                events.append(['enqueue', nid, rng.choice(flows), rng.randint(1, maxlen),
                               rng.randint(0, 100)])
                nid += 1
        elif c < 0.97:
            name = rng.randint(0, 2)
            events.append(['save', name]); save_names.append(name)
        else:
            events.append(['restore', rng.choice(save_names) if save_names else (save_names.append(0) or 0)])
    return {'banks': M, 'load_balancers': L, 'fifo_bytes': fcap,
            'pifo_bytes': pcap, 'refill_batch': batch, 'sample_period': period,
            'borders': borders, 'policy': policy, 'events': events}


def main():
    seed0 = int(sys.argv[1]); count = int(sys.argv[2])
    bad = 0
    for it in range(count):
        rng = random.Random(seed0 * 77777 + it)
        mode = 'edge' if it % 2 else 'wide'
        nruns = rng.randint(1, 4)
        specs = [gen_run(rng, mode) for _ in range(nruns)]
        request = {'runs': specs}
        try:
            got = run_request(request)['runs']
        except Exception:
            import traceback; traceback.print_exc()
            print('ENGINE CRASH', it); print(json.dumps(request)); bad += 1
            if bad > 1: return 1
            continue
        try:
            exp = [ref.run(s) for s in specs]
        except Exception as exc:
            print('REF CRASH', it, exc); print(json.dumps(request)); bad += 1
            if bad > 1: return 1
            continue
        if not same(got, exp):
            bad += 1
            print('MISMATCH iter', it, mode)
            print(json.dumps(request))
            for r, (g, e) in enumerate(zip(got, exp)):
                for a, b in zip(g['log'], e['log']):
                    if a != b:
                        print('run', r, 'log got ', a); print('run', r, 'log exp ', b); break
                if len(g['log']) != len(e['log']):
                    print('run', r, 'log lengths', len(g['log']), len(e['log']))
                for key in g['state']:
                    if not same(g['state'][key], e['state'][key]):
                        print('run', r, 'state', key); print('  got', json.dumps(g['state'][key])[:300])
                        print('  exp', json.dumps(e['state'][key])[:300])
            if bad > 1: return 1
    print('fuzz2 done:', count, 'requests,', bad, 'mismatches')
    return 1 if bad else 0


sys.exit(main())
